INSERT INTO conflict_rules (active_ingredient_a, active_ingredient_b, severity, reason_vi, recommendation_vi) VALUES ('Retinol', 'Salicylic Acid (BHA)', 'Warning', 'Phá vỡ hàng rào bảo vệ da, gây bong tróc nặng và bỏng rát.', 'Dùng BHA tối 2-4-6, Retinol tối 3-5-7.');
INSERT INTO conflict_rules (active_ingredient_a, active_ingredient_b, severity, reason_vi, recommendation_vi) VALUES ('Retinol', 'Glycolic Acid (AHA)', 'Warning', 'Kích ứng mạnh, bào mòn lớp sừng bề mặt da.', 'Dùng AHA sáng hoặc cách ngày, Retinol dùng buổi tối.');
INSERT INTO conflict_rules (active_ingredient_a, active_ingredient_b, severity, reason_vi, recommendation_vi) VALUES ('Benzoyl Peroxide', 'Retinol', 'Contraindication', 'Benzoyl Peroxide oxy hóa làm mất hoạt tính của Retinol.', 'Dùng Benzoyl Peroxide buổi sáng, Retinol buổi tối.');
INSERT INTO conflict_rules (active_ingredient_a, active_ingredient_b, severity, reason_vi, recommendation_vi) VALUES ('Vitamin C (L-Ascorbic Acid)', 'Salicylic Acid (BHA)', 'Warning', 'pH quá thấp làm da quá tải acid, gây đỏ rát châm chích.', 'Dùng Vitamin C buổi sáng trước kem chống nắng, BHA buổi tối.');
INSERT INTO conflict_rules (active_ingredient_a, active_ingredient_b, severity, reason_vi, recommendation_vi) VALUES ('Vitamin C (L-Ascorbic Acid)', 'Glycolic Acid (AHA)', 'Warning', 'Môi trường acid quá mạnh gây bỏng rát da nhạy cảm.', 'Dùng Vitamin C buổi sáng, AHA buổi tối.');
INSERT INTO conflict_rules (active_ingredient_a, active_ingredient_b, severity, reason_vi, recommendation_vi) VALUES ('Vitamin C (L-Ascorbic Acid)', 'Niacinamide', 'Warning', 'Có thể tương tác tạo phức Niacin làm ửng đỏ da tạm thời ở nồng độ cao.', 'Thoa cách nhau 20 phút hoặc chia sáng (Vit C) / tối (Niacinamide).');
INSERT INTO conflict_rules (active_ingredient_a, active_ingredient_b, severity, reason_vi, recommendation_vi) VALUES ('Benzoyl Peroxide', 'Vitamin C (L-Ascorbic Acid)', 'Contraindication', 'Benzoyl Peroxide là chất oxy hóa mạnh, triệt tiêu tác dụng của Vitamin C.', 'Tách riêng Benzoyl Peroxide buổi tối và Vitamin C buổi sáng.');
INSERT INTO conflict_rules (active_ingredient_a, active_ingredient_b, severity, reason_vi, recommendation_vi) VALUES ('Retinol', 'Vitamin C (L-Ascorbic Acid)', 'Warning', 'Cả hai đều là hoạt chất đặc trị mạnh, pH hoạt động chênh lệch dễ gây kích ứng.', 'Vitamin C buổi sáng chống oxy hóa, Retinol buổi tối tái tạo da.');
INSERT INTO conflict_rules (active_ingredient_a, active_ingredient_b, severity, reason_vi, recommendation_vi) VALUES ('Glycolic Acid (AHA)', 'Salicylic Acid (BHA)', 'Warning', 'Nguy cơ tẩy da chết quá đà (Over-exfoliation) nếu dùng cùng lúc.', 'Không thoa chung nếu da nhạy cảm; chia xen kẽ ngày.');
INSERT INTO conflict_rules (active_ingredient_a, active_ingredient_b, severity, reason_vi, recommendation_vi) VALUES ('Hydroquinone', 'Benzoyl Peroxide', 'Contraindication', 'Có thể gây sạm đen da tạm thời do phản ứng kết tủa.', 'Tuyệt đối không dùng chung trong cùng chu trình.');
INSERT INTO conflict_rules (active_ingredient_a, active_ingredient_b, severity, reason_vi, recommendation_vi) VALUES ('Copper Peptides', 'Vitamin C (L-Ascorbic Acid)', 'Warning', 'Ion đồng oxy hóa acid ascorbic, làm mất tác dụng của cả hai hoạt chất.', 'Dùng Peptide buổi sáng, Vitamin C buổi tối (hoặc ngược lại).');
INSERT INTO conflict_rules (active_ingredient_a, active_ingredient_b, severity, reason_vi, recommendation_vi) VALUES ('Retinol', 'Scrub', 'Warning', 'Tổn thương vi mô kết hợp bong sừng gây viêm da tiếp xúc.', 'Không dùng scrub dạng hạt vật lý khi đang treatment Retinol.');
