INSERT INTO products (code, name, slug, brand_id, category_id, price_vnd, volume_ml, description, image_url, ingredient_list_raw, target_skin_types, stock_quantity) VALUES ('P420652', 'Lip Sleeping Mask Intense Hydration with Vitamin C', 'lip-sleeping-mask-intense-hydration-with-vitamin-c-p420652', (SELECT id FROM brands WHERE name = 'LANEIGE' LIMIT 1), (SELECT id FROM categories WHERE name = 'Lip Balms & Treatments' LIMIT 1), 600000, 50, 'allure 2019 Best of Beauty Award Winner, Community Favorite, Vitamin C, Hydrating, Good for: Dryness, Without Parabens', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?w=500&q=80', 'diisostearyl malate, hydrogenated polyisobutene, phyto- steryl/isostearyl/cetyl/stearyl/behenyl dimer dilinoleate, hydrogenated poly(c6-14 olefin), polybutene, microcrystalline wax / cera microcristallina / cire microcri stalline, butyrospermum parkii (shea) butter, synthetic wax, ethylene/propylene/styrene copolymer, sucrose tetrastearate triacetate, mica, euphorbia cerifera (candelilla) wax / candelilla cera hydrocarbons / cire de candelilla, candelilla wax esters, astrocaryum murumuru seed butter, titanium dioxide (ci 77891), fragrance / parfum, glyceryl caprylate, polyglyceryl-2 diisostearate, butylene/ethylene/styrene copolymer, copernicia cerifera (carnauba) wax / copernicia cerifera cera / cire de carnauba, methicone, polyglyceryl-2 triisostearate, cocos nucifera (coconut) oil, yellow 6 lake (ci 15985), pentaerythrityl tetra-di-t-butyl hydroxyhydrocinnamate, red 6 (ci 15850), ascorbic acid, water / aqua / eau, glycerin, propanediol, bht, punica granatum fruit juice, rubus idaeus (raspberry) juice, vitis vinifera (grape) juice', ARRAY['Oily', 'Combination'], 100) ON CONFLICT (code) DO NOTHING;
